/* Fade, rise and un-blur over the first 220px of scroll after the element's top enters the
   window (a fixed distance, so tall cards in the first screen are already clear at load). The
   step number shifts the range by 40px so items in a row arrive one after another. Only where
   the browser supports view timelines and the visitor allows motion; otherwise everything is
   simply there. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .plumeform-v2-reveal {
      animation: plumeform-v2-reveal-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--plumeform-v2-reveal-step, 0) * 40px) entry calc(220px + var(--plumeform-v2-reveal-step, 0) * 40px);
    }
  }
}

@keyframes plumeform-v2-reveal-in {
  from {
    opacity: 0;
    transform: translateY(22px);
    filter: blur(6px);
  }
  to {
    opacity: 1;
    transform: none;
    filter: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./plumeform-v2-reveal.css";

export interface PlumeformV2RevealProps {
  children?: ReactNode;
  /** the element to render (div by default; li inside lists) */
  as?: ElementType;
  /** position in a staggered row: 0, 1, 2… each arrives a little later */
  step?: number;
  className?: string;
}

export function PlumeformV2Reveal({ children, as: Tag = "div", step = 0, className }: PlumeformV2RevealProps) {
  return (
    <Tag className={cn("plumeform-v2-reveal", className)} style={{ "--plumeform-v2-reveal-step": step } as CSSProperties}>
      {children}
    </Tag>
  );
}
